def apply_descriptions(model: Any) -> None:
    """Set ``description`` on every field of *model* that has none and has an entry above."""
    for name, field in model.model_fields.items():
        if not (field.description or "").strip() and name in FIELD_DESCRIPTIONS:
            field.description = FIELD_DESCRIPTIONS[name]


__all__ = ["FIELD_DESCRIPTIONS", "apply_descriptions"]
